// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {StaxLPStaking} from "../src/StaxLPStaking.sol";

contract InvMutTest is Test {
    StaxLPStaking c;
    function setUp() public { c = new StaxLPStaking(address(this), address(this)); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0));
        c.transferOwnership(newOwner);
        bool success;
        address returnedOwner;
        try c.owner() returns (address o) {
            success = true;
            returnedOwner = o;
        } catch {
            success = false;
        }
        assertTrue(success && returnedOwner == newOwner);
    }
}
